package com.example.smartpantrymanager.adapter;
import android.view.*;import android.widget.*;import androidx.recyclerview.widget.RecyclerView;import com.example.smartpantrymanager.R;import com.example.smartpantrymanager.model.PantryItem;import java.util.*;
public class PantryAdapter extends RecyclerView.Adapter<PantryAdapter.VH>{public interface Listener{void edit(PantryItem p);void delete(PantryItem p);}private List<PantryItem> data;private Listener listener;public PantryAdapter(List<PantryItem>d,Listener l){data=d;listener=l;}public void setData(List<PantryItem>d){data=d;notifyDataSetChanged();}public VH onCreateViewHolder(ViewGroup p,int v){return new VH(LayoutInflater.from(p.getContext()).inflate(R.layout.item_pantry,p,false));}public void onBindViewHolder(VH h,int i){PantryItem x=data.get(i);h.name.setText(x.getName());h.qty.setText(x.getQuantity()+" "+x.getUnit()+(x.getExpiryDate()==null||x.getExpiryDate().isEmpty()?"":" • Expires "+x.getExpiryDate()));h.edit.setOnClickListener(v->listener.edit(x));h.del.setOnClickListener(v->listener.delete(x));}public int getItemCount(){return data.size();}static class VH extends RecyclerView.ViewHolder{TextView name,qty;Button edit,del;VH(View v){super(v);name=v.findViewById(R.id.itemName);qty=v.findViewById(R.id.itemQty);edit=v.findViewById(R.id.btnEdit);del=v.findViewById(R.id.btnDelete);}}}
